phase1.code:
// ---- Struct definition ----
struct Player {
    name: String,
    health: i32,
    attack: i32,
    defense: i32,
    level: i32,
}

// ---- Tuple struct ----
struct Position(i32, i32, i32);

// ---- Unit struct (no fields) ----
struct Empty;

fn main() {
    // ---- Creating a struct instance ----
    let hero = Player {
        name: String::from("Hero"),
        health: 100,
        attack: 20,
        defense: 10,
        level: 1,
    };

    // ---- Accessing fields ----
    println!("Name: {}", hero.name);
    println!("Health: {}", hero.health);
    println!("Attack: {}", hero.attack);
    println!("Defense: {}", hero.defense);
    println!("Level: {}", hero.level);

    // ---- Mutable struct ----
    let mut enemy = Player {
        name: String::from("Goblin"),
        health: 30,
        attack: 8,
        defense: 3,
        level: 1,
    };

    enemy.health -= 10;
    println!("\nEnemy health: {}", enemy.health);

    // ---- Tuple struct ----
    let pos = Position(10, 20, 5);
    println!("Position: ({}, {}, {})", pos.0, pos.1, pos.2);

    // ---- Struct update syntax ----
    let hero2 = Player {
        name: String::from("Aragorn"),
        health: 120,
        ..hero  // Use remaining fields from hero
    };

    println!("\nHero2:");
    println!("Name: {}", hero2.name);
    println!("Health: {}", hero2.health);
    println!("Attack: {}", hero2.attack);

    // ---- Unit struct ----
    let _empty = Empty;

    // ---- Struct with functions ----
    let player = Player::new("Legolas", 90, 25, 12, 2);
    player.display();
}

// ---- Methods on structs ----
impl Player {
    // Associated function (constructor)
    fn new(name: &str, health: i32, attack: i32, defense: i32, level: i32) -> Player {
        Player {
            name: String::from(name),
            health,
            attack,
            defense,
            level,
        }
    }

    // Method (takes &self)
    fn display(&self) {
        println!("\n=== Player ===");
        println!("Name: {}", self.name);
        println!("Health: {}", self.health);
        println!("Attack: {}", self.attack);
        println!("Defense: {}", self.defense);
        println!("Level: {}", self.level);
    }

    // Method with &mut self
    fn take_damage(&mut self, damage: i32) {
        self.health -= damage;
        if self.health < 0 {
            self.health = 0;
        }
    }

    // Method with self (takes ownership)
    fn into_string(self) -> String {
        format!("{} (Lv. {}, HP: {})", self.name, self.level, self.health)
    }
}

